BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (951::BIGINT, 'una malparida'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-03-11T00:00:00+00:00'::TIMESTAMPTZ, '87a07bd8ea522b1c07a29b03b7e78d0f8d26bc04bf673a7cf2ee85d3be31ec21'::TEXT, ARRAY[1369]::BIGINT[]),
    (951::BIGINT, 'buena gente la princesa Fiona'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2024-04-23T00:00:00+00:00'::TIMESTAMPTZ, 'da78059ce125cfca90db6e6520a78daf001ba0e5fe79563d61984edaadb9e319'::TEXT, ARRAY[3007]::BIGINT[]),
    (951::BIGINT, 'Es buena profe, no da muchas explicaciones pero si uno pide ayuda ella la da. El asistente tarda bastante el publicar las notas de las evaluaciones pero no califica duro.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-16T00:00:00+00:00'::TIMESTAMPTZ, '957d0b08c9fd3e74e8e9dcb0cf05a7e9b1e25e9990380931aec82c6360de341c'::TEXT, ARRAY[3050]::BIGINT[]),
    (951::BIGINT, 'Las clases son llevaderas. Por lo menos un 50% de la materia se debe aprender a puro libro, que en realidad contiene todo lo necesario para pasar el curso si lo lleva con ella y no con Iván. Vaya rapidito cuando resuelve el examen porque da muy poco tiempo para resolverlo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2023-11-25T00:00:00+00:00'::TIMESTAMPTZ, '88a47b9dd42f6cb2df991b6b79ba10a86a2250528fa816a149c020f28c27b101'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'Es una profe “normal” digamos, no espere nada fuera de lo usual, solo entregue todo a tiempo y pasa'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores']::TEXT[], '2023-06-29T00:00:00+00:00'::TIMESTAMPTZ, '4aa43f06195911e44ab7139a1cd053fbbe446fcff0df496b158cfe1bec2eea21'::TEXT, ARRAY[3050]::BIGINT[]),
    (951::BIGINT, 'Cae muy bien, pero definitivamente no sería mi primer opción. A veces es un poco difícil de tratar y a como puede hacer un examen muy fácil, el siguiente lo hace muy difícil.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '1d2fa458cf17d56f86db03d8e7bfd4dc468bcb6ffe2e1a1cab81aa418e9fcd9c'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'La profe es buena en general, explica bastante bien los ejercicios y trata de explicar varios durante la clase. Las clases son lentas y es bastante materia pero si le pone la entiende bastante bien. Los exámenes son difíciles pero si estudia se pueden hacer, se parecen a los ejercicios en clase.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '4e40861b154f8e7ca652524825b4066b4996ae1813cbfde33fb8dc3caf32b84c'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'Los quices a veces pueden ser un poco complicados, pero es comprensiva y depende sustituye la nota más baja por otra alta. Ponga de su parte y la profe será pura vida con usted.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '8ed96f75c5f05486d078974f5827e288bc95c2d34f966d73ee6b7d4a25d12312'::TEXT, ARRAY[927, 3050]::BIGINT[]),
    (951::BIGINT, 'En Virtual. Deja trabajos semanales que no revisa al final del curso y no proporciona retroalimentacion de los mismos. Explica lento, lo cual es bueno y malo, porque termina entendiendo un tipo de ejercicio muy bien, pero lo logra abarcar otros tipos de ejercicios.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes']::TEXT[], '2022-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'f9ef47f2a5acea0cd9adae10825e1f0495f1715f23c457408a220c08b66d1d05'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'La profe excplica muy bien en virtual, da las clases con ayuda del ipad y hace ejercicios a nivel de examen. Me gustaron mucho sus clases, explica lento que es lo que me gusta y no duda en ayudar o dar puntos extra. No me parece tan mala profe como dicen... una de mis profes favoritas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Clases excelentes']::TEXT[], '2021-12-22T00:00:00+00:00'::TIMESTAMPTZ, '55002717cf7ce66a4ecf2801e0ed297f5aca0c3f66316663eb6ba27859b95242'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'Se aprende más solo con el libro, hay que hacer más ejercicios que los que ella de como ejemplo para examen, porque de los que ella da, ninguno sale. Hay guías semanales, pero son de mentiras porque ni retroalimentación da y ni las revisa. Es buena persona, pero enseñar es otra cosa.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'bbb94c10a96425d0f3e035d4d3548bbe6f02891baedb9522b8844659021bee49'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'La profesora es buena gente y explica bien la materia del curso (que debería llamarse solo “Probabilidad”, lo de procesos casi ni se vio). Eso sí, hace los exámenes con pocos puntos y no revisa las guías semanales. No es tan mala como dicen.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, '4c84a3f8eff31788fb98567d29c3344e5136ad465435dda8b16f4b80fa54e063'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'Aprendí más leyendo del libro que en las clases. Martuca se tira de vergazos con Don Iván para ver quién es el profe más malo de Meca. Sin duda alguna le gana por KO técnico en el 5to round.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-09-14T00:00:00+00:00'::TIMESTAMPTZ, '1007b3ae7b65498cf9f0bbf4a0ea5cf3bbf3c93c26840d3660a593eae79d631f'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'Mucha irresponsabilidad de parte de ella, es demasiado desordenada. Ya había subido actas y ni siquiera nos había enviado el último parcial. Se puede estudiar solo con el libro'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'c0bf9db63210362a3f1078066331778b87f96c63b1d053422c91a6ab3ec340f6'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'Di el curso se pasa, pero Marta es muy desordenanda con las evaluaciones. La verdad no hace ni falta ir a clase, el libro tiene todo lo que ocupa para entender la materia.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '5087c8da22fe90ce84160a6207bc99061e7f83559911a3a5f3007f256a500058'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'Como persona, es excelente, pero es una pésima profesora, y de las peores. No busca mejorar, ya que deja "guías de estudio" pero no las revisa en clase para dar retroalimentación de lo que uno hizo. Los exámenes no son tan complicados, pero es un dolor que acepte reclamos, aunque tengan sentido.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-02-25T00:00:00+00:00'::TIMESTAMPTZ, 'ddd4d28931c0410e3325acdddb0d4f4ff05a5770a6c67910dc3efad2484228a8'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'En resumen, hace curva al final ya que el segundo examen lo hace para que nadie lo pase, con hacer todos los trabajos y sacarse 100 en el proyecto y laboratorios etc, se pasa fácil aún teniendo los exámenes bajos (por la curva), eso sí el curso es una decepción no vaya con expectativas altas.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'c65a6bd94524bf2a0c74de606cd8e39ea643c49ee26f3d7976e6e7d09632eaa9'::TEXT, ARRAY[3007]::BIGINT[]),
    (951::BIGINT, 'Da más días de consulta que clases, deja "guías de estudio" cuestionarios sin posterior retroalimentación, no guían. El enfoque del curso es puro cálculo matricial, "califica" duro lograr reclamos es prácticamente un milagro, dura 1.5h resolviendo un problema enredándose, examen: 2.5h y 3 problemas'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '5bf596b488cd5872640d2d0134736acf94f6f78c0f5ad17108effaef2478a8f8'::TEXT, ARRAY[3007]::BIGINT[]),
    (951::BIGINT, 'Revisa increíblemente duro, quitando todos los puntos en problemas por el mínimo error. El curso lo da a mala gana porque no le gusta la virtualidad. Es muy difícil reclamarle cosas y cuesta que responda correos. En resumen, de los peores profesores de mecatrónica, tal vez incluso la peor.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'a9bf421e1ba40970ec2101bcd32e5530e071fb155059fb44656410ba2b0a1b86'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'Demasiado prepotente. Ella acepta que no le gusta la virtualidad, por lo que el curso lo da muy mal. Manda unas guías y sus presentaciones son super básicas. No ayuda a que uno comprenda. En los exámenes baja puntos por TODO, solo para que usted no saque buena nota. Realmente NO vale la pena.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'd4b4e134be97371b45ecebbde58ca634e949c183ebfbdb1c3613a6aa64126e04'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, '70% del curso es resolver matrices a mano y 30% aprendizaje de conceptos/herramientas útiles de robótica. No espere un curso dónde vaya a obtener conocimientos directamente aplicables a la industria. Los exámenes tienen una dificultad razonable, pero el tiempo que da para realizarlos es un chiste.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'c025117c8827a7111297493f09816ab9b988f851c9971a4fe47a7dc0aae126e8'::TEXT, ARRAY[3007]::BIGINT[]),
    (951::BIGINT, 'Pésima. De lo peor de mecatrónica. En serio debería retirarse ya.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos exámenes']::TEXT[], '2020-11-13T00:00:00+00:00'::TIMESTAMPTZ, '258ddfef9332b0d0177f20aaf78fe31a95d4c2c20e2f2f849f4050c862eefa57'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, '5comentarios'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '99e4bd494e2056bf73aca1ce2538c2cef0a16d6464f57fc4ef2f3e8c58fe434b'::TEXT, ARRAY[3007]::BIGINT[]),
    (951::BIGINT, 'Es demasiado desorganizada y la materia de las clases se da con mucho desorden, a veces no da materia por semanas y después mete todo en guías de estudio para semana 16. Las evaluaciones están mal redactadas y tienen errores.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '1abd0771b6d1343f4f434410260870184ebc757f6638c99c1a96d0e68f7dccae'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'Personalmente pienso que ya no está para dar clases, redacta mal el material de clase y las evaluaciones, evalúa con criterio confuso y no siguió un buen cronograma para el curso. En lo positivo es excelente persona y profesional, cae bien y es divertida'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'b9a81eec731659b4de065bf44018d6185dc02eacded4514444c575c55933c829'::TEXT, ARRAY[3061]::BIGINT[]),
    (951::BIGINT, 'Solo se vio la mitad del libro del curso, que en sí tiene muy pocos ejemplos para la mayoría de los temas, entonces no hay de donde estudiar. Los exámenes se pasan con el tiempo y los revisa sin criterio. En los ejemplos que hace se la pasa confundiéndose. El curso se pasa pero se sufre.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '2dc5c8124300d590af99172b319ef50d36c8e93e0827246f4c5994bbfb10200d'::TEXT, ARRAY[3007]::BIGINT[]),
    (951::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '339a5ff0d240add0571df8e07e998f7faed2e79ba29dcaffd15bf22dfd2abf2a'::TEXT, ARRAY[3007]::BIGINT[]),
    (951::BIGINT, 'sígale la correinte y listo..... acomplejada'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'defe6a72bf0bd4a4d9728cbdee52b5baf2d70a9adb856369ef473f17d241f619'::TEXT, ARRAY[3050]::BIGINT[]),
    (951::BIGINT, 'A veces califica suave al final para que la gente pase. Asume que todos ya saben cómo hacer todo con el equipo y se leyeron absolutamente todos los manuales. En clases no hay que esperar aprender nada, sólo por cuenta propia. Pro tip: Si uno es de física puede que le caiga mejor a ella.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '49ca5e4cd88dca1ad9d17f01165e4aa4da61a3704227a1956b4556e262c3037b'::TEXT, ARRAY[3050]::BIGINT[]),
    (951::BIGINT, 'Excelente profe, es un poco seria pero tan solo hay que ser amable y seguir siempre sus instrucciones y se vuelve muy sencillo. Se le entiende bastante bien y da instrucciones claras.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-10-23T00:00:00+00:00'::TIMESTAMPTZ, 'aa555f6a9b482f95d069ed329c477655cead447b9c44e6683f9441a0814158c4'::TEXT, ARRAY[3050]::BIGINT[]),
    (951::BIGINT, 'No espere que le explique nada, ni espere que le ayude. Casi siempre hace mala cara cuando le preguntan y en general no revisa que es lo que uno está haciendo mal. Excelente persona, pésima profesora.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, '2ddd7490adff62793f701e536bc0c80f36639f086357ecf79bb6cd6198d5302a'::TEXT, ARRAY[3050]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
